  (self : NLAlib.IsGreedyOddMinimax q ell c l u) (k : ℕ) :
  ∃ x ∈ Set.Icc (l k) (u k), NLAlib.oddScalarUpdate q (c k) x = l (k + 1)

NLAlib.IsGreedyOddMinimax.attain_upper {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
  (self : NLAlib.IsGreedyOddMinimax q ell c l u) (k : ℕ) :
  ∃ x ∈ Set.Icc (l k) (u k), NLAlib.oddScalarUpdate q (c k) x = u (k + 1)

NLAlib.IsGreedyOddMinimax.bounds {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
  (self : NLAlib.IsGreedyOddMinimax q ell c l u) (k : ℕ) (x : ℝ) :
  x ∈ Set.Icc (l k) (u k) → l (k + 1) ≤ NLAlib.oddScalarUpdate q (c k) x ∧ NLAlib.oddScalarUpdate q (c k) x ≤ u (k + 1)

NLAlib.IsGreedyOddMinimax.composition_error_le {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
  (h : NLAlib.IsGreedyOddMinimax q ell c l u) (hell : 0 < ell) (hell1 : ell ≤ 1) {T : ℕ} (hT : 1 ≤ T) {x : ℝ}
  (hx : x ∈ Set.Icc ell 1) : |1 - NLAlib.oddScalarComposition q c x T| ≤ 1 - l T ∧ 1 - l T ≤ (1 - ell ^ 2) ^ (q + 1) ^ T

NLAlib.IsGreedyOddMinimax.composition_mem_interval {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
