  NLAlib.oddScalarComposition q c x k ∈ Set.Icc (l k) (u k)

NLAlib.IsGreedyOddMinimax.normalized_images {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
  (h : NLAlib.IsGreedyOddMinimax q ell c l u) (hell : 0 < ell) (hell1 : ell ≤ 1) (k : ℕ) :
  l (k + 1) + u (k + 1) = 2 ∧ NLAlib.oddUniformError q (c k) (l k) (u k) = 1 - l (k + 1)

NLAlib.IsGreedyOddMinimax.squared_ratio_gap_le {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
  (h : NLAlib.IsGreedyOddMinimax q ell c l u) (hell : 0 < ell) (hell1 : ell ≤ 1) (k : ℕ) :
  1 - (l k / u k) ^ 2 ≤ (1 - ell ^ 2) ^ (q + 1) ^ k

NLAlib.IsGreedyOddMinimax.uniform_error_le {q : ℕ} {ell : ℝ} {c : ℕ → ℕ → ℝ} {l u : ℕ → ℝ}
  (h : NLAlib.IsGreedyOddMinimax q ell c l u) (hell : 0 < ell) (hell1 : ell ≤ 1) (k : ℕ) :
  NLAlib.oddUniformError q (c k) (l k) (u k) ≤ (1 - ell ^ 2) ^ (q + 1) ^ (k + 1)

