  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq m] [DecidableEq n] [DecidableEq r] {B : Matrix m n 𝕜}
  {Z : Matrix n r 𝕜} (hZ : NLAlib.IsKernelFrame B Z) (hB : IsUnit (B * B.conjTranspose)) (v : n → 𝕜) :
  v = Z.mulVec (Z.conjTranspose.mulVec v) + B.conjTranspose.mulVec ((B * B.conjTranspose)⁻¹.mulVec (B.mulVec v))

