  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq m] [DecidableEq n] [DecidableEq r] {B : Matrix m n 𝕜}
  {Z : Matrix n r 𝕜} (hZ : NLAlib.IsKernelFrame B Z) (hB : IsUnit (B * B.conjTranspose)) (H : Matrix n n 𝕜) :
  IsUnit (NLAlib.kktMatrix H B) ↔ IsUnit (NLAlib.reducedHessian H Z)

NLAlib.IsKernelFrame.kkt_solution.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq m] [DecidableEq n] [DecidableEq r] {B : Matrix m n 𝕜}
  {Z : Matrix n r 𝕜} (hZ : NLAlib.IsKernelFrame B Z) (hB : IsUnit (B * B.conjTranspose)) (H : Matrix n n 𝕜) (f : n → 𝕜)
  (g : m → 𝕜) (xp : n → 𝕜) (hxp : B.mulVec xp = g) (y : r → 𝕜)
  (hy : (NLAlib.reducedHessian H Z).mulVec y = Z.conjTranspose.mulVec (f - H.mulVec xp)) :
  have x := xp + Z.mulVec y;
  have l := (B * B.conjTranspose)⁻¹.mulVec (B.mulVec (f - H.mulVec x));
  B.mulVec x = g ∧ H.mulVec x + B.conjTranspose.mulVec l = f

