NLAlib.IsMatrixSign.projectors.{u_1} {n : Type u_1} [Fintype n] [DecidableEq n] {A S : Matrix n n ℂ}
  (hS : NLAlib.IsMatrixSign A S) :
  have P := 2⁻¹ • (1 + S);
  have Q := 2⁻¹ • (1 - S);
  P * P = P ∧ Q * Q = Q ∧ P * Q = 0 ∧ Q * P = 0 ∧ P + Q = 1

