  (c s : n → ℝ) : Prop

NLAlib.IsNormalizedGSVD.common_kernel_iff.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜} {L : Matrix p n 𝕜}
  {X : Matrix n n 𝕜} {c s : n → ℝ} (h : NLAlib.IsNormalizedGSVD A L X c s) (y : n → 𝕜) :
  A.mulVec (X.mulVec y) = 0 ∧ L.mulVec (X.mulVec y) = 0 ↔ ∀ (i : n), c i ^ 2 + s i ^ 2 = 1 → y i = 0

NLAlib.IsNormalizedGSVD.generalTikhonovFilter_minimizer.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2}
  {n : Type u_3} {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜}
  {L : Matrix p n 𝕜} {X : Matrix n n 𝕜} {c s : n → ℝ} (h : NLAlib.IsNormalizedGSVD A L X c s) (b : m → 𝕜) {β : ℝ}
  (hβ : 0 < β) (z : n → 𝕜) :
  NLAlib.generalTikhonovObjective A L b β (NLAlib.generalTikhonovFilter A X c s b β) ≤
    NLAlib.generalTikhonovObjective A L b β z

NLAlib.IsNormalizedGSVD.generalTikhonovNormal_congruence.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2}
  {n : Type u_3} {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜}
  {L : Matrix p n 𝕜} {X : Matrix n n 𝕜} {c s : n → ℝ} (h : NLAlib.IsNormalizedGSVD A L X c s) (β : ℝ) :
  X.conjTranspose * NLAlib.generalTikhonovNormal A L β * X = Matrix.diagonal fun i => ↑(c i ^ 2 + β * s i ^ 2)

NLAlib.IsNormalizedGSVD.invertible.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
