NLAlib.IsNormalizedGSVD.left_gram.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜} {L : Matrix p n 𝕜}
  {X : Matrix n n 𝕜} {c s : n → ℝ} (self : NLAlib.IsNormalizedGSVD A L X c s) :
  X.conjTranspose * (A.conjTranspose * A) * X = Matrix.diagonal fun i => ↑(c i) ^ 2

NLAlib.IsNormalizedGSVD.left_nonneg.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
