NLAlib.IsNormalizedGSVD.left_orthonormal.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜} {L : Matrix p n 𝕜}
  {X : Matrix n n 𝕜} {c s : n → ℝ} (h : NLAlib.IsNormalizedGSVD A L X c s) :
  NLAlib.HasOrthonormalCols (Matrix.of fun i j => (A * X) i ↑j / ↑(c ↑j))

NLAlib.IsNormalizedGSVD.normalized.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜} {L : Matrix p n 𝕜}
  {X : Matrix n n 𝕜} {c s : n → ℝ} (self : NLAlib.IsNormalizedGSVD A L X c s) (i : n) :
  c i ^ 2 + s i ^ 2 = 0 ∨ c i ^ 2 + s i ^ 2 = 1

NLAlib.IsNormalizedGSVD.rank_stack_eq_card_active.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2}
  {n : Type u_3} {p : Type u_4} [Fintype m] [Fintype n] [Fintype p] [DecidableEq n] {A : Matrix m n 𝕜}
  {L : Matrix p n 𝕜} {X : Matrix n n 𝕜} {c s : n → ℝ} (h : NLAlib.IsNormalizedGSVD A L X c s) :
  (A.fromRows L).rank = Fintype.card { i // c i ^ 2 + s i ^ 2 = 1 }

NLAlib.IsNormalizedGSVD.right_col_eq_zero.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
