  {X : Matrix n n 𝕜} {c s : n → ℝ} (self : NLAlib.IsNormalizedGSVD A L X c s) :
  X.conjTranspose * (L.conjTranspose * L) * X = Matrix.diagonal fun i => ↑(s i) ^ 2

NLAlib.IsNormalizedGSVD.right_nonneg.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
