  (hR : ∀ (i : n), R i i ≠ 0) : Q * Q.conjTranspose = A * NLAlib.moorePenroseInverse A

NLAlib.IsQR.norm_sub_mulVec_sq_eq.{u_1} {m : Type u_1} [Fintype m] {n : ℕ} {A Q : Matrix m (Fin n) ℝ}
  {R : Matrix (Fin n) (Fin n) ℝ} (h : NLAlib.IsQR A Q R) (hR : ∀ (i : Fin n), R i i ≠ 0) {b : m → ℝ} {x : Fin n → ℝ}
  (hx : NLAlib.IsLeastSquaresSolution A b x) :
  ‖WithLp.toLp 2 (b - A.mulVec x)‖ ^ 2 = ‖WithLp.toLp 2 b‖ ^ 2 - ‖WithLp.toLp 2 (Q.transpose.mulVec b)‖ ^ 2

NLAlib.IsQR.range_mulVecLin_eq.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} [Fintype m] {n : Type u_3}
