NLAlib.IsSVD.frobInner_mul_rectDiag_mul_conjTranspose.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2}
  {n : Type u_3} [Fintype m] [Fintype n] [DecidableEq m] [DecidableEq n] {p q : ℕ} {A : Matrix m n 𝕜}
  {U : Matrix m (Fin p) 𝕜} {V : Matrix n (Fin q) 𝕜} (h : NLAlib.IsSVD A U V) (b : ℕ → ℝ) :
  NLAlib.frobInner A (U * NLAlib.rectDiag b * V.conjTranspose) =
    ∑ i ∈ Finset.range (min p q), NLAlib.singularValues A i * b i

NLAlib.IsSVD.frobSq_sub_truncatedMatrix.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
