NLAlib.IsSVD.mul_headColumns_projector {m n k : ℕ} {A : Matrix (Fin m) (Fin n) ℝ} {U : Matrix (Fin m) (Fin m) ℝ}
  {V : Matrix (Fin n) (Fin n) ℝ} (h : NLAlib.IsSVD A U V) (hkn : k ≤ n) :
  A * (NLAlib.headColumns V hkn * (NLAlib.headColumns V hkn).transpose) = h.truncatedMatrix k

NLAlib.IsSVD.mul_right.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3} [Fintype m] [Fintype n]
  [DecidableEq m] [DecidableEq n] {p q : ℕ} {A : Matrix m n 𝕜} {U : Matrix m (Fin p) 𝕜} {V : Matrix n (Fin q) 𝕜}
  (h : NLAlib.IsSVD A U V) : A * V = U * NLAlib.rectDiag (NLAlib.singularValues A)

NLAlib.IsSVD.rank_truncatedMatrix_le.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3} [Fintype m]
  [Fintype n] [DecidableEq n] [DecidableEq m] {p q : ℕ} {A : Matrix m n 𝕜} {U : Matrix m (Fin p) 𝕜}
  {V : Matrix n (Fin q) 𝕜} (h : NLAlib.IsSVD A U V) (k : ℕ) : (h.truncatedMatrix k).rank ≤ k

NLAlib.IsSVD.residual_headColumns_eq_sub_truncatedMatrix {m n k : ℕ} {A : Matrix (Fin m) (Fin n) ℝ}
  {U : Matrix (Fin m) (Fin m) ℝ} {V : Matrix (Fin n) (Fin n) ℝ} (h : NLAlib.IsSVD A U V) (hkm : k ≤ m) :
  NLAlib.projResidual (NLAlib.headColumns U hkm) A = A - h.truncatedMatrix k

NLAlib.IsSVD.residual_headColumns_transpose_eq_sub_truncatedMatrix_transpose {m n k : ℕ} {A : Matrix (Fin m) (Fin n) ℝ}
  {U : Matrix (Fin m) (Fin m) ℝ} {V : Matrix (Fin n) (Fin n) ℝ} (h : NLAlib.IsSVD A U V) (hkn : k ≤ n) :
  NLAlib.projResidual (NLAlib.headColumns V hkn) A.transpose = (A - h.truncatedMatrix k).transpose

NLAlib.IsSVD.schattenDualCoefficients_attain.{u_1} {𝕜 : Type u_1} [RCLike 𝕜] {m n : ℕ} {A : Matrix (Fin m) (Fin n) 𝕜}
  {U : Matrix (Fin m) (Fin m) 𝕜} {V : Matrix (Fin n) (Fin n) 𝕜} (h : NLAlib.IsSVD A U V) {p q : ℝ}
  (hpq : p.HolderConjugate q) (hA : A ≠ 0) :
  NLAlib.schattenNormReal (U * NLAlib.rectDiag (NLAlib.schattenDualCoefficients A p) * V.conjTranspose) q = 1 ∧
    NLAlib.frobInner A (U * NLAlib.rectDiag (NLAlib.schattenDualCoefficients A p) * V.conjTranspose) =
      NLAlib.schattenNormReal A p

NLAlib.IsSVD.specNorm_sub_truncatedMatrix.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  [Fintype m] [Fintype n] [DecidableEq n] [DecidableEq m] {p q : ℕ} {A : Matrix m n 𝕜} {U : Matrix m (Fin p) 𝕜}
  {V : Matrix n (Fin q) 𝕜} (h : NLAlib.IsSVD A U V) (k : ℕ) :
  NLAlib.specNorm (A - h.truncatedMatrix k) = NLAlib.singularValues A k

NLAlib.IsSVD.sub_truncatedMatrix_mul_headColumns_eq_zero {m n k : ℕ} {A : Matrix (Fin m) (Fin n) ℝ}
  {U : Matrix (Fin m) (Fin m) ℝ} {V : Matrix (Fin n) (Fin n) ℝ} (h : NLAlib.IsSVD A U V) (hkn : k ≤ n) :
  (A - h.truncatedMatrix k) * NLAlib.headColumns V hkn = 0

NLAlib.IsSVD.truncatedMatrix.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3} [Fintype m]
  [Fintype n] [DecidableEq n] [DecidableEq m] {p q : ℕ} {A : Matrix m n 𝕜} {U : Matrix m (Fin p) 𝕜}
  {V : Matrix n (Fin q) 𝕜} (_h : NLAlib.IsSVD A U V) (k : ℕ) : Matrix m n 𝕜

NLAlib.IsSVD.truncatedMatrix_transpose {m n : ℕ} {A : Matrix (Fin m) (Fin n) ℝ} {U : Matrix (Fin m) (Fin m) ℝ}
  {V : Matrix (Fin n) (Fin n) ℝ} (h : NLAlib.IsSVD A U V) (k : ℕ) :
  ⋯.truncatedMatrix k = (h.truncatedMatrix k).transpose

NLAlib.IsSingularTripletFamily.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] (A : Matrix m n 𝕜) (U : Matrix m r 𝕜)
  (V : Matrix n r 𝕜) (σ : r → ℝ) : Prop

NLAlib.IsSingularTripletFamily.adjoint_mul_left.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2}
  {n : Type u_3} {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜}
  {U : Matrix m r 𝕜} {V : Matrix n r 𝕜} {σ : r → ℝ} (self : NLAlib.IsSingularTripletFamily A U V σ) :
  A.conjTranspose * U = V * Matrix.diagonal fun i => ↑(σ i)

NLAlib.IsSingularTripletFamily.full_gramian_balancing.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {n : Type u_2}
  {a : Type u_3} {b : Type u_4} [Fintype n] [Fintype a] [Fintype b] [DecidableEq n] [DecidableEq a] [DecidableEq b]
  {R : Matrix n a 𝕜} {O U : Matrix b n 𝕜} {V : Matrix a n 𝕜} {σ : n → ℝ}
  (h : NLAlib.IsSingularTripletFamily (O * R) U V σ) :
  have T := NLAlib.balancingTrialMap R V σ;
  have Φ := NLAlib.balancingTestMap O U σ;
  IsUnit T ∧
    T⁻¹ = Φ.conjTranspose ∧
      (T⁻¹ * (R * R.conjTranspose) * T⁻¹.conjTranspose = Matrix.diagonal fun i => ↑(σ i)) ∧
        (T.conjTranspose * (O.conjTranspose * O) * T = Matrix.diagonal fun i => ↑(σ i)) ∧
          T⁻¹ * (R * R.conjTranspose * (O.conjTranspose * O)) * T = Matrix.diagonal fun i => ↑(σ i) ^ 2

NLAlib.IsSingularTripletFamily.gramian_balancing.{u_1, u_2, u_3, u_4, u_5} {𝕜 : Type u_1} [RCLike 𝕜] {n : Type u_2}
  {a : Type u_3} {b : Type u_4} {r : Type u_5} [Fintype n] [Fintype a] [Fintype b] [Fintype r] [DecidableEq n]
  [DecidableEq a] [DecidableEq b] [DecidableEq r] {R : Matrix n a 𝕜} {O : Matrix b n 𝕜} {U : Matrix b r 𝕜}
  {V : Matrix a r 𝕜} {σ : r → ℝ} (h : NLAlib.IsSingularTripletFamily (O * R) U V σ) :
  have Ψ := NLAlib.balancingTrialMap R V σ;
  have Φ := NLAlib.balancingTestMap O U σ;
  Φ.conjTranspose * Ψ = 1 ∧
    (Φ.conjTranspose * (R * R.conjTranspose) * Φ = Matrix.diagonal fun i => ↑(σ i)) ∧
      Ψ.conjTranspose * (O.conjTranspose * O) * Ψ = Matrix.diagonal fun i => ↑(σ i)

NLAlib.IsSingularTripletFamily.left_orth.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (self : NLAlib.IsSingularTripletFamily A U V σ) : NLAlib.HasOrthonormalCols U

NLAlib.IsSingularTripletFamily.mk.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (left_orth : NLAlib.HasOrthonormalCols U) (right_orth : NLAlib.HasOrthonormalCols V)
  (pos : ∀ (i : r), 0 < σ i) (mul_right : A * V = U * Matrix.diagonal fun i => ↑(σ i))
  (adjoint_mul_left : A.conjTranspose * U = V * Matrix.diagonal fun i => ↑(σ i)) :
  NLAlib.IsSingularTripletFamily A U V σ

NLAlib.IsSingularTripletFamily.mul_right.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (self : NLAlib.IsSingularTripletFamily A U V σ) :
  A * V = U * Matrix.diagonal fun i => ↑(σ i)

NLAlib.IsSingularTripletFamily.pos.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (self : NLAlib.IsSingularTripletFamily A U V σ) (i : r) : 0 < σ i

NLAlib.IsSingularTripletFamily.right_orth.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (self : NLAlib.IsSingularTripletFamily A U V σ) : NLAlib.HasOrthonormalCols V

NLAlib.IsSingularTripletFamily.specNorm_truncatedSingularInverse.{u_1, u_2, u_3} {𝕜 : Type u_1} [RCLike 𝕜]
  {m : Type u_2} {n : Type u_3} [Fintype m] [Fintype n] [DecidableEq m] [DecidableEq n] {k : ℕ} {A : Matrix m n 𝕜}
  {U : Matrix m (Fin k) 𝕜} {V : Matrix n (Fin k) 𝕜}
  (h : NLAlib.IsSingularTripletFamily A U V fun i => NLAlib.singularValues A ↑i) (hk : 0 < k) :
  NLAlib.specNorm (NLAlib.truncatedSingularInverse U V fun i => NLAlib.singularValues A ↑i) =
    1 / NLAlib.singularValues A (k - 1)

NLAlib.IsSingularTripletFamily.submatrix_cols.{u_1, u_2, u_3, u_4, u_5} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2}
  {n : Type u_3} {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜}
  {U : Matrix m r 𝕜} {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsSingularTripletFamily A U V σ) {s : Type u_5}
  [Fintype s] [DecidableEq s] (e : s ↪ r) :
  NLAlib.IsSingularTripletFamily A (U.submatrix id ⇑e) (V.submatrix id ⇑e) fun i => σ (e i)

NLAlib.IsSubspaceEmbedding.mul_right.{u_1, u_2, u_3, u_4} {k : Type u_1} {m : Type u_2} {d : Type u_3} {e : Type u_4}
  [Fintype k] [Fintype m] [Fintype d] [Fintype e] {S : Matrix k m ℝ} {U : Matrix m d ℝ} {ε : ℝ}
  (h : NLAlib.IsSubspaceEmbedding S U ε) (C : Matrix d e ℝ) : NLAlib.IsSubspaceEmbedding S (U * C) ε

NLAlib.IsSubspaceEmbedding.of_mul_right.{u_1, u_2, u_3, u_4} {k : Type u_1} {m : Type u_2} {d : Type u_3} {e : Type u_4}
  [Fintype k] [Fintype m] [Fintype d] [Fintype e] [DecidableEq d] {S : Matrix k m ℝ} {U : Matrix m d ℝ} {ε : ℝ}
  {C : Matrix d e ℝ} {D : Matrix e d ℝ} (hCD : C * D = 1) (h : NLAlib.IsSubspaceEmbedding S (U * C) ε) :
  NLAlib.IsSubspaceEmbedding S U ε

NLAlib.IsThinSVD.canonicalPartialPolar_eq.{u_1, u_2, u_3} {m : Type u_1} {n : Type u_2} {r : Type u_3} [Fintype m]
  [Fintype n] [Fintype r] [DecidableEq n] [DecidableEq r] {A : Matrix m n ℂ} {U : Matrix m r ℂ} {V : Matrix n r ℂ}
  {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) : NLAlib.canonicalPartialPolar A = U * V.conjTranspose

NLAlib.IsThinSVD.card_le_of_markovParameters_eq.{u_1, u_2, u_3, u_4, u_5} {𝕜 : Type u_1} [RCLike 𝕜] {n : Type u_2}
  {p : Type u_3} {q : Type u_4} [Fintype n] [Fintype p] [Fintype q] [DecidableEq n] [DecidableEq p] [DecidableEq q]
  {A : Matrix n n 𝕜} {B : Matrix n q 𝕜} {C : Matrix p n 𝕜} {s t : ℕ} {U : Matrix (Fin s × p) n 𝕜}
  {V : Matrix (Fin t × q) n 𝕜} {σ : n → ℝ} (h : NLAlib.IsThinSVD (NLAlib.blockHankel A B C s t 0) U V σ) {k : Type u_5}
  [Fintype k] [DecidableEq k] (A' : Matrix k k 𝕜) (B' : Matrix k q 𝕜) (C' : Matrix p k 𝕜)
  (hdata : ∀ j < s + t - 1, C * A ^ j * B = C' * A' ^ j * B') : Fintype.card n ≤ Fintype.card k

NLAlib.IsThinSVD.dmdOperator_eq.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {n : Type u_2} {m : Type u_3}
  {r : Type u_4} [Fintype n] [Fintype m] [Fintype r] [DecidableEq n] [DecidableEq m] [DecidableEq r] {X : Matrix n m 𝕜}
  {U : Matrix n r 𝕜} {V : Matrix m r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD X U V σ) (Y : Matrix n m 𝕜) :
  NLAlib.dmdOperator X Y = NLAlib.dmdModeMap Y V σ * U.conjTranspose

NLAlib.IsThinSVD.eq.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3} {r : Type u_4}
  [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜} {V : Matrix n r 𝕜}
  {σ : r → ℝ} (self : NLAlib.IsThinSVD A U V σ) : A = (U * Matrix.diagonal fun i => ↑(σ i)) * V.conjTranspose

NLAlib.IsThinSVD.era_markovParameter.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {n : Type u_2} {p : Type u_3}
  {q : Type u_4} [Fintype n] [Fintype p] [Fintype q] [DecidableEq n] [DecidableEq p] [DecidableEq q] {A : Matrix n n 𝕜}
  {B : Matrix n q 𝕜} {C : Matrix p n 𝕜} {s t : ℕ} (hs : 0 < s) (ht : 0 < t) {U : Matrix (Fin s × p) n 𝕜}
  {V : Matrix (Fin t × q) n 𝕜} {σ : n → ℝ} (h : NLAlib.IsThinSVD (NLAlib.blockHankel A B C s t 0) U V σ) (j : ℕ) :
  NLAlib.eraOutputMatrix U σ (NLAlib.firstBlockOutput s hs) *
        NLAlib.eraStateMatrix (NLAlib.blockHankel A B C s t 1) U V σ ^ j *
      NLAlib.eraInputMatrix V σ (NLAlib.firstBlockInput t ht) =
    C * A ^ j * B

NLAlib.IsThinSVD.era_similarity.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {n : Type u_2} {p : Type u_3}
  {q : Type u_4} [Fintype n] [Fintype p] [Fintype q] [DecidableEq n] [DecidableEq p] [DecidableEq q] {A : Matrix n n 𝕜}
  {B : Matrix n q 𝕜} {C : Matrix p n 𝕜} {s t : ℕ} (hs : 0 < s) (ht : 0 < t) {U : Matrix (Fin s × p) n 𝕜}
  {V : Matrix (Fin t × q) n 𝕜} {σ : n → ℝ} (h : NLAlib.IsThinSVD (NLAlib.blockHankel A B C s t 0) U V σ) :
  have T := NLAlib.balancingTrialMap (NLAlib.controllabilityArray A B t) V σ;
  IsUnit T ∧
    NLAlib.eraStateMatrix (NLAlib.blockHankel A B C s t 1) U V σ = T⁻¹ * A * T ∧
      NLAlib.eraInputMatrix V σ (NLAlib.firstBlockInput t ht) = T⁻¹ * B ∧
        NLAlib.eraOutputMatrix U σ (NLAlib.firstBlockOutput s hs) = C * T

NLAlib.IsThinSVD.isSingularTripletFamily.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) : NLAlib.IsSingularTripletFamily A U V σ

NLAlib.IsThinSVD.landweberIterate_zero_eq.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  [Fintype m] [Fintype n] [DecidableEq m] [DecidableEq n] {r : Type u_4} [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜}
  {U : Matrix m r 𝕜} {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) (b : m → 𝕜) (η : ℝ) (t : ℕ) :
  NLAlib.landweberIterate A b η 0 t =
    ((V * Matrix.diagonal fun i => ↑((1 - (1 - η * σ i ^ 2) ^ t) / σ i)) * U.conjTranspose).mulVec b

NLAlib.IsThinSVD.landweberStepMatrix_mul.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  [Fintype m] [Fintype n] [DecidableEq m] [DecidableEq n] {r : Type u_4} [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜}
  {U : Matrix m r 𝕜} {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) (η : ℝ) :
  (NLAlib.landweberStepMatrix A η * V = V * Matrix.diagonal fun i => ↑(1 - η * σ i ^ 2)) ∧
    NLAlib.landweberStepMatrix A η * (1 - V * V.conjTranspose) = 1 - V * V.conjTranspose

NLAlib.IsThinSVD.landweberStepMatrix_pow.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  [Fintype m] [Fintype n] [DecidableEq m] [DecidableEq n] {r : Type u_4} [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜}
  {U : Matrix m r 𝕜} {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) (η : ℝ) (t : ℕ) :
  NLAlib.landweberStepMatrix A η ^ t =
    1 - V * V.conjTranspose + (V * Matrix.diagonal fun i => ↑((1 - η * σ i ^ 2) ^ t)) * V.conjTranspose

NLAlib.IsThinSVD.left_orth.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3} {r : Type u_4}
  [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜} {V : Matrix n r 𝕜}
  {σ : r → ℝ} (self : NLAlib.IsThinSVD A U V σ) : NLAlib.HasOrthonormalCols U

NLAlib.IsThinSVD.mk.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3} {r : Type u_4}
  [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜} {V : Matrix n r 𝕜}
  {σ : r → ℝ} (left_orth : NLAlib.HasOrthonormalCols U) (right_orth : NLAlib.HasOrthonormalCols V)
  (pos : ∀ (i : r), 0 < σ i) (eq : A = (U * Matrix.diagonal fun i => ↑(σ i)) * V.conjTranspose) :
  NLAlib.IsThinSVD A U V σ

NLAlib.IsThinSVD.moorePenroseInverse_eq.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) :
  NLAlib.moorePenroseInverse A = (V * Matrix.diagonal fun i => (↑(σ i))⁻¹) * U.conjTranspose

NLAlib.IsThinSVD.moorePenroseInverse_mul_eq.{u_1, u_2, u_3, u_4} {𝕜 : Type u_1} [RCLike 𝕜] {m : Type u_2} {n : Type u_3}
  {r : Type u_4} [Fintype m] [Fintype n] [Fintype r] [DecidableEq r] {A : Matrix m n 𝕜} {U : Matrix m r 𝕜}
  {V : Matrix n r 𝕜} {σ : r → ℝ} (h : NLAlib.IsThinSVD A U V σ) : NLAlib.moorePenroseInverse A * A = V * V.conjTranspose

