  {n : Type u_2} {s : Type u_3} {J : Type u_4} [Fintype m] [Fintype n] [Fintype s] [Fintype J] [MeasurableSpace J]
  [MeasurableSingletonClass J] {Ω : Type u_5} [MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω} (A : Matrix m n ℝ)
  (b : m → ℝ) (p : J → ℝ) (hp : ∀ (j : J), 0 ≤ p j) (hp1 : ∑ j, p j = 1) (S : J → Matrix m s ℝ) {xs : n → ℝ}
  (hxs : A.mulVec xs = b) {lam : ℝ}
  (hlam :
    ∀ v ∈ A.transpose.mulVecLin.range,
      lam * ‖WithLp.toLp 2 v‖ ^ 2 ≤ v ⬝ᵥ (NLAlib.SketchProject.expectedProjector A p S).mulVec v)
  (x : n → ℝ) (hx : x - xs ∈ A.transpose.mulVecLin.range) (k : ℕ) {H : Ω → Fin k → J}
  (hH : ProbabilityTheory.HasLaw H (NLAlib.SketchProject.pathLaw p hp hp1 k) μ) :
  ∫ (ω : Ω), ‖WithLp.toLp 2 (NLAlib.SketchProject.run A b S k (H ω) x - xs)‖ ^ 2 ∂μ ≤
    (1 - lam) ^ k * ‖WithLp.toLp 2 (x - xs)‖ ^ 2

