        ProbabilityTheory.covariance (fun p => NLAlib.resamplingTripleOriginal p i)
          (fun p => NLAlib.resamplingTripleOriginal p j) (NLAlib.resamplingTripleMeasure ν))
  (A : Matrix n n ℂ) (hA : A.IsHermitian) (ζ : ℂ) (hζ : ζ.im ≠ 0) {t : ℝ} (ht : 0 < t) (ht1 : t < 1) :
