NLAlib.matrixSign_spectral_projectors.{u_1} {n : Type u_1} [Fintype n] [DecidableEq n] {A : Matrix n n ℂ}
  (hA : ∀ z ∈ spectrum ℂ A, z.re ≠ 0) :
  have S := NLAlib.matrixSign A;
  have P := 2⁻¹ • (1 + S);
  have Q := 2⁻¹ • (1 - S);
  NLAlib.IsMatrixSign A S ∧
    P * P = P ∧
      Q * Q = Q ∧
        P * Q = 0 ∧
          Q * P = 0 ∧
            P + Q = 1 ∧
              (Matrix.toLin' P).range = NLAlib.matrixSpectralSubspace A {z | 0 < z.re} ∧
                (Matrix.toLin' Q).range = NLAlib.matrixSpectralSubspace A {z | z.re < 0}

