Real.resolvent_variance_and_gamma_scale_le {R E Q v ℓ p δ η : ℝ} (hQ : 0 ≤ Q) (hp : 0 ≤ p) (hδ : 0 ≤ δ) (hη : 0 < η)
  (hδη : δ ≤ η) (hvp : v * p ≤ δ ^ 2) (hRE : R * E * p ≤ 3 * δ ^ 2) (hRQ : R ^ 2 * Q * p ≤ δ ^ 4)
  (hRℓ : R ^ 4 * ℓ * p ≤ δ ^ 4) (hRp : R ^ 2 * p ^ 2 ≤ δ ^ 2) (hR4p : R ^ 4 * p ^ 2 ≤ δ ^ 4) :
  have B := 2 / η ^ 4 * (8 * v + 64 * R * E) + 32 * R ^ 2 / η ^ 6 * ((Real.exp 1 - 1) * Q + R ^ 2 * ℓ);
  have c := √(6 * (16 * R ^ 2 / η ^ 4 + 64 * R ^ 4 / η ^ 6));
  B * p ≤ 500 * (δ / η ^ 2) ^ 2 ∧ c * p ≤ 22 * (δ / η ^ 2)

