  (hℓ : ℓ ≤ p) (hsp : s * √p ≤ δ) (hRp : R * p ≤ δ) (hcube : R * σ ^ 2 * p ^ 2 ≤ δ ^ 3) :
  have B := 2 / η ^ 4 * (8 * s ^ 2 + 64 * R * E) + 32 * R ^ 2 / η ^ 6 * ((Real.exp 1 - 1) * Q + R ^ 2 * ℓ);
  have c := √(6 * (16 * R ^ 2 / η ^ 4 + 64 * R ^ 4 / η ^ 6));
